import{_ as i,o as n,c as e,a2 as t}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Posisi Fundamental Realitas sebagai Dasar","description":"","frontmatter":{},"headers":[],"relativePath":"id/09-现实为基根本立场.md","filePath":"id/09-现实为基根本立场.md","lastUpdated":1789183869000}'),s={name:"id/09-现实为基根本立场.md"};function r(d,a,k,u,l,m){return n(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="posisi-fundamental-realitas-sebagai-dasar" tabindex="-1">Posisi Fundamental Realitas sebagai Dasar <a class="header-anchor" href="#posisi-fundamental-realitas-sebagai-dasar" aria-label="Permalink to &quot;Posisi Fundamental Realitas sebagai Dasar&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Proyek</th><th>Isi</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>09</td></tr><tr><td>Modul</td><td>Prinsip Umum dan Pengaturan Inti</td></tr><tr><td>Kata Kunci Utama</td><td>Realitas sebagai Dasar, Realitas Tunggal, Batas Fiksi, Pembaruan Hukum, Verifikasi Praktis</td></tr></tbody></table><h2 id="i-definisi-dasar-realitas-sebagai-dasar" tabindex="-1">I. Definisi Dasar Realitas sebagai Dasar <a class="header-anchor" href="#i-definisi-dasar-realitas-sebagai-dasar" aria-label="Permalink to &quot;I. Definisi Dasar Realitas sebagai Dasar&quot;">​</a></h2><p>Realitas sebagai dasar adalah posisi epistemologis fundamental dan prinsip metodologis Peradaban Simbiosis Jangkar, yang berarti bahwa semua konstruksi teoretis, desain institusional, praktik latihan, dan inovasi teknologi peradaban harus mengambil dunia nyata sebagai satu-satunya dasar nyata dan kriteria verifikasi akhir. &quot;Realitas&quot; merujuk pada dunia material dan dunia energi yang ada secara objektif, dapat dipersepsikan, diukur, dan diverifikasi, dan merupakan tempat nyata bagi kelangsungan hidup dan evolusi kehidupan.</p><p>Posisi realitas sebagai dasar mengandung tiga lapisan makna: pertama, dunia nyata adalah satu-satunya dunia nyata, dan dunia fiksi (termasuk novel, mitos, dan dunia fantasi) adalah produk eksperimen mental dan tidak memiliki realitas objektif; kedua, pengaturan dunia fiksi dapat digunakan sebagai sumber inspirasi dan alat eksperimen mental, tetapi tidak dapat digunakan langsung sebagai dasar realitas, dan harus melewati verifikasi dan transformasi hukum nyata; ketiga, hal-hal yang belum ada dalam realitas dapat disimpulkan dan diciptakan secara wajar berdasarkan hukum objektif yang telah diverifikasi, tetapi penciptaan ini harus menerima verifikasi praktik.</p><h2 id="ii-mengapa-harus-bersikeras-pada-realitas-sebagai-dasar" tabindex="-1">II. Mengapa harus bersikeras pada Realitas sebagai Dasar <a class="header-anchor" href="#ii-mengapa-harus-bersikeras-pada-realitas-sebagai-dasar" aria-label="Permalink to &quot;II. Mengapa harus bersikeras pada Realitas sebagai Dasar&quot;">​</a></h2><h3 id="_2-1-mencegah-kebingungan-antara-fiksi-dan-realitas" tabindex="-1">2.1 Mencegah kebingungan antara fiksi dan realitas <a class="header-anchor" href="#_2-1-mencegah-kebingungan-antara-fiksi-dan-realitas" aria-label="Permalink to &quot;2.1 Mencegah kebingungan antara fiksi dan realitas&quot;">​</a></h3><p>Dalam peradaban latihan, pengaturan dunia fiksi sering kali memiliki daya tarik yang kuat. Banyak kultivator mendapatkan inspirasi latihan dari novel, mitos, dan legenda, yang pada dasarnya adalah hal yang normal. Tetapi jika pengaturan dunia fiksi langsung disamakan dengan hukum nyata, itu akan menyebabkan masalah serius: berlatih sesuai dengan pengaturan fiksi dapat menyebabkan penyimpangan latihan, merumuskan institusi berdasarkan pengaturan fiksi dapat menyebabkan pelepasan dari realitas, memperlakukan karakter fiksi sebagai idola nyata dapat menyebabkan kebingungan mental. Fungsi utama posisi realitas sebagai dasar adalah menarik batas antara fiksi dan realitas, dan mencegah kebingungan keduanya.</p><h3 id="_2-2-menjamin-keamanan-dan-efektivitas-praktik-latihan" tabindex="-1">2.2 Menjamin keamanan dan efektivitas praktik latihan <a class="header-anchor" href="#_2-2-menjamin-keamanan-dan-efektivitas-praktik-latihan" aria-label="Permalink to &quot;2.2 Menjamin keamanan dan efektivitas praktik latihan&quot;">​</a></h3><p>Latihan adalah praktik serius yang melibatkan asal-usul kehidupan dan pengoperasian energi, dan teori apa pun yang salah dapat menyebabkan konsekuensi serius. Sistem latihan di dunia fiksi sering kali dirancang oleh penulis untuk kebutuhan alur cerita, dan mungkin tidak sesuai dengan hukum pengoperasian energi nyata dan hukum evolusi kehidupan. Jika kultivator menyalin pengaturan fiksi tanpa membedakan, dalam kasus ringan latihan akan tidak efektif dan membuang waktu, dalam kasus berat akan terjadi gangguan energi, penyimpangan latihan, bahkan bahaya kehidupan. Posisi realitas sebagai dasar menuntut agar semua teori latihan melewati verifikasi dan validasi realitas, menjamin keamanan dan efektivitas praktik latihan.</p><h3 id="_2-3-menjaga-pragmatisme-institusi-peradaban" tabindex="-1">2.3 Menjaga pragmatisme institusi peradaban <a class="header-anchor" href="#_2-3-menjaga-pragmatisme-institusi-peradaban" aria-label="Permalink to &quot;2.3 Menjaga pragmatisme institusi peradaban&quot;">​</a></h3><p>Desain institusi peradaban harus didasarkan pada faktor objektif seperti kondisi sosial nyata, situasi sumber daya, dan hubungan ras. Jika terlepas dari realitas, dan hanya berdasarkan imajinasi indah atau pengaturan fiksi untuk mendesain institusi, institusi akan menjadi istana di udara dan tidak dapat diimplementasikan dalam praktik. Posisi realitas sebagai dasar menuntut agar semua desain institusi dimulai dari realitas, melewati verifikasi praktik, dan terus disesuaikan serta ditingkatkan sesuai dengan perubahan realitas.</p><h3 id="_2-4-menyediakan-metodologi-yang-andal-untuk-inovasi-dan-penciptaan" tabindex="-1">2.4 Menyediakan metodologi yang andal untuk inovasi dan penciptaan <a class="header-anchor" href="#_2-4-menyediakan-metodologi-yang-andal-untuk-inovasi-dan-penciptaan" aria-label="Permalink to &quot;2.4 Menyediakan metodologi yang andal untuk inovasi dan penciptaan&quot;">​</a></h3><p>Realitas sebagai dasar tidak berarti membatasi inovasi dan imajinasi, tetapi menyediakan metodologi yang andal untuk inovasi dan imajinasi. Fiksi dapat digunakan sebagai sumber inspirasi dan alat eksperimen mental, tetapi penciptaan nyata harus didasarkan pada pemahaman mendalam tentang hukum nyata. Hal-hal yang tidak ada dalam realitas, selama sesuai dengan hukum objektif, dapat diciptakan; tetapi jika melanggar hukum objektif, seindah apa pun imajinasinya, tidak dapat menjadi kenyataan. Posisi realitas sebagai dasar menggabungkan &quot;imajinasi berani&quot; dengan &quot;verifikasi hati-hati&quot;, membuat inovasi didasarkan pada dasar yang kokoh.</p><h2 id="iii-prinsip-penanganan-hubungan-antara-fiksi-dan-realitas" tabindex="-1">III. Prinsip Penanganan Hubungan antara Fiksi dan Realitas <a class="header-anchor" href="#iii-prinsip-penanganan-hubungan-antara-fiksi-dan-realitas" aria-label="Permalink to &quot;III. Prinsip Penanganan Hubungan antara Fiksi dan Realitas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prinsip</th><th>Isi</th><th>Persyaratan Spesifik</th></tr></thead><tbody><tr><td>Prinsip Pembedaan</td><td>Membedakan secara ketat pengaturan fiksi dan hukum nyata</td><td>Setiap teori harus menunjukkan dengan jelas apakah asalnya adalah inspirasi fiksi atau verifikasi nyata</td></tr><tr><td>Prinsip Penyerapan</td><td>Fiksi dapat digunakan sebagai sumber inspirasi dan eksperimen mental</td><td>Mendorong mendapatkan inspirasi dari fiksi, tetapi harus melewati transformasi hukum nyata</td></tr><tr><td>Prinsip Verifikasi</td><td>Semua teori harus melewati verifikasi praktik nyata</td><td>Teori yang belum diverifikasi hanya dapat digunakan sebagai hipotesis, bukan sebagai dasar untuk mengarahkan praktik</td></tr><tr><td>Prinsip Transformasi</td><td>Pengaturan fiksi harus diubah menjadi bentuk yang sesuai dengan hukum nyata</td><td>Mengekspresikan kembali konsep dalam fiksi dengan bahasa energi dan ilmu hukum nyata</td></tr><tr><td>Prinsip Batas</td><td>Hak dan kewajiban di dunia fiksi tidak meluas ke realitas</td><td>Tidak mengakui validitas identitas, kontrak, dan kausalitas di dunia fiksi dalam realitas</td></tr></tbody></table><h2 id="iv-kekurangan-fiksi-dilengkapi-dengan-realitas-apa-yang-tidak-ada-dalam-realitas-diciptakan-berdasarkan-pembaruan-hukum" tabindex="-1">IV. &quot;Kekurangan fiksi dilengkapi dengan realitas, apa yang tidak ada dalam realitas diciptakan berdasarkan pembaruan hukum&quot; <a class="header-anchor" href="#iv-kekurangan-fiksi-dilengkapi-dengan-realitas-apa-yang-tidak-ada-dalam-realitas-diciptakan-berdasarkan-pembaruan-hukum" aria-label="Permalink to &quot;IV. &quot;Kekurangan fiksi dilengkapi dengan realitas, apa yang tidak ada dalam realitas diciptakan berdasarkan pembaruan hukum&quot;&quot;">​</a></h2><p>Ini adalah prinsip operasional inti dari posisi realitas sebagai dasar, dan mengandung dua aspek:</p><h3 id="_4-1-kekurangan-fiksi-dilengkapi-dengan-realitas" tabindex="-1">4.1 Kekurangan fiksi dilengkapi dengan realitas <a class="header-anchor" href="#_4-1-kekurangan-fiksi-dilengkapi-dengan-realitas" aria-label="Permalink to &quot;4.1 Kekurangan fiksi dilengkapi dengan realitas&quot;">​</a></h3><p>Ketika inspirasi atau pengaturan yang diperoleh dari dunia fiksi tidak cukup lengkap, tidak konsisten sendiri, atau tidak sesuai dengan hukum nyata, maka harus dilengkapi dan dikoreksi dengan pengetahuan dan hukum yang telah diverifikasi dalam realitas. Misalnya, sistem latihan tertentu dalam fiksi mungkin hanya menjelaskan pembagian tingkat tanpa menjelaskan mekanisme pengoperasian energi, maka perlu menggunakan teori siklus energi nyata untuk melengkapi mekanisme pengoperasiannya; teknologi tertentu dalam fiksi mungkin melanggar hukum dasar konservasi energi, maka perlu menggunakan hukum nyata untuk mengoreksi pengaturannya.</p><p>Proses pelengkapan bukan hanya sekadar menggabungkan fiksi dan realitas, tetapi mengambil hukum nyata sebagai kerangka, mengatur kembali elemen yang wajar dalam fiksi menjadi sistem teoretis yang konsisten sendiri dan sesuai dengan hukum nyata.</p><h3 id="_4-2-apa-yang-tidak-ada-dalam-realitas-diciptakan-berdasarkan-pembaruan-hukum" tabindex="-1">4.2 Apa yang tidak ada dalam realitas diciptakan berdasarkan pembaruan hukum <a class="header-anchor" href="#_4-2-apa-yang-tidak-ada-dalam-realitas-diciptakan-berdasarkan-pembaruan-hukum" aria-label="Permalink to &quot;4.2 Apa yang tidak ada dalam realitas diciptakan berdasarkan pembaruan hukum&quot;">​</a></h3><p>Ketika sesuatu atau kemampuan tertentu belum ada dalam realitas, tetapi kemungkinan keberadaannya dapat disimpulkan berdasarkan hukum objektif yang telah diverifikasi, maka dapat dilakukan pembaruan dan penciptaan yang wajar berdasarkan hukum. Penciptaan ini bukan imajinasi tanpa dasar, melainkan perluasan logis dan implementasi teknologi berdasarkan hukum yang ada.</p><p>Misalnya, penerapan teknologi buah penggandaan adalah kasus khas dari &quot;penciptaan berdasarkan pembaruan hukum&quot;. Buah penggandaan awalnya berasal dari pengaturan karya fiksi, tetapi peneliti peradaban simbiosis mengekspresikan kembali mekanisme intinya (amplifikasi penggandaan) dengan bahasa energi dan ilmu hukum nyata, dan berdasarkan hukum amplifikasi energi dan resonansi hukum, mengembangkan teknologi penggandaan yang dapat diimplementasikan secara teknis. Proses ini menggunakan inspirasi fiksi dan pada saat yang sama secara ketat mengikuti hukum nyata.</p><p>Hasil penciptaan harus melewati verifikasi praktik. Hanya penciptaan yang diverifikasi efektif, aman, dan stabil dalam realitas yang dapat dimasukkan ke dalam sistem formal peradaban simbiosis.</p><h2 id="v-penerapan-realitas-sebagai-dasar-di-berbagai-bidang" tabindex="-1">V. Penerapan Realitas sebagai Dasar di Berbagai Bidang <a class="header-anchor" href="#v-penerapan-realitas-sebagai-dasar-di-berbagai-bidang" aria-label="Permalink to &quot;V. Penerapan Realitas sebagai Dasar di Berbagai Bidang&quot;">​</a></h2><h3 id="_5-1-di-bidang-latihan" tabindex="-1">5.1 Di bidang latihan <a class="header-anchor" href="#_5-1-di-bidang-latihan" aria-label="Permalink to &quot;5.1 Di bidang latihan&quot;">​</a></h3><p>Semua sistem latihan harus melewati proses &quot;verifikasi nyata&quot;: dari konstruksi teoretis hingga eksperimen skala kecil, kemudian promosi skala besar, setiap tahap harus memiliki data efek yang dapat diukur dan direproduksi. Metode latihan yang belum melewati verifikasi nyata hanya dapat digunakan sebagai &quot;metode eksperimental&quot;, dengan indikasi risiko, dan tidak dapat dipromosikan sebagai sistem formal.</p><h3 id="_5-2-di-bidang-teknologi" tabindex="-1">5.2 Di bidang teknologi <a class="header-anchor" href="#_5-2-di-bidang-teknologi" aria-label="Permalink to &quot;5.2 Di bidang teknologi&quot;">​</a></h3><p>Semua teknologi rekayasa hukum harus mengikuti proses pengembangan &quot;secara teoretis layak — verifikasi eksperimental — implementasi teknologi — evaluasi keamanan&quot;. Dasar teoretis teknologi harus merupakan hukum objektif yang telah diverifikasi, efek teknologi harus memiliki indikator yang dapat diukur, dan keamanan teknologi harus melewati evaluasi yang ketat.</p><h3 id="_5-3-di-bidang-institusi-sosial" tabindex="-1">5.3 Di bidang institusi sosial <a class="header-anchor" href="#_5-3-di-bidang-institusi-sosial" aria-label="Permalink to &quot;5.3 Di bidang institusi sosial&quot;">​</a></h3><p>Semua desain institusi sosial harus didasarkan pada investigasi sosial nyata dan analisis data. Perubahan institusi besar harus terlebih dahulu diuji dalam skala kecil, dan kemudian dipromosikan secara bertahap setelah evaluasi efek. Kriteria evaluasi institusi harus merupakan indikator nyata yang dapat diukur, bukan konsep abstrak atau pengaturan fiksi.</p><h3 id="_5-4-di-bidang-sejarah-dan-arkeologi" tabindex="-1">5.4 Di bidang sejarah dan arkeologi <a class="header-anchor" href="#_5-4-di-bidang-sejarah-dan-arkeologi" aria-label="Permalink to &quot;5.4 Di bidang sejarah dan arkeologi&quot;">​</a></h3><p>Penelitian tentang peristiwa sejarah dan peradaban kuno harus didasarkan pada bukti material dan sumber sejarah yang dapat diverifikasi. Konten legenda dan mitos dapat digunakan sebagai objek penelitian budaya, tetapi tidak dapat digunakan langsung sebagai fakta sejarah. Pekerjaan arkeologi mengikuti rencana polusi rendah dari &quot;cermin salinan + arkeologi di tempat terisolasi yang berbeda, hanya mengembalikan pengetahuan&quot;, menjamin bahwa pekerjaan arkeologi tidak mengubah realitas sejarah.</p><h2 id="vi-pemahaman-mendalam-tentang-konsep-realitas" tabindex="-1">VI. Pemahaman Mendalam tentang Konsep &quot;Realitas&quot; <a class="header-anchor" href="#vi-pemahaman-mendalam-tentang-konsep-realitas" aria-label="Permalink to &quot;VI. Pemahaman Mendalam tentang Konsep &quot;Realitas&quot;&quot;">​</a></h2><p>Perlu dicatat secara khusus bahwa &quot;realitas&quot; dalam posisi realitas sebagai dasar bukanlah konsep statis dan tertutup, melainkan konsep dinamis yang terus dipahami dan diperluas.</p><p>Pertama, cakupan realitas terus meluas seiring dengan perkembangan peradaban. Fenomena yang di masa lalu dianggap &quot;supranatural&quot;, dengan pemahaman mendalam tentang energi dan hukum, telah dimasukkan ke dalam cakupan realitas. Mekanisme jangkar, perjalanan antar-bidang, interaksi domain kesadaran, dll., mungkin tampak &quot;fiksi&quot; dari sudut pandang peradaban rendah, tetapi dalam realitas peradaban tinggi ada secara objektif.</p><p>Kedua, pemahaman tentang hukum nyata terus mendalam. Teori yang hari ini dianggap &quot;hukum&quot; mungkin di masa depan dikoreksi atau digantikan oleh teori yang lebih mendalam. Posisi realitas sebagai dasar tidak berarti mempertahankan pemahaman yang ada secara kaku, tetapi memegang teguh metode mendasar dari &quot;praktik sebagai satu-satunya kriteria untuk memverifikasi kebenaran&quot;, dan terus memperdalam pemahaman tentang realitas.</p><p>Ketiga, realitas mengandung kemungkinan yang tak terbatas. Berdasarkan hukum yang ada, kita dapat menyimpulkan banyak kemungkinan yang belum terwujud, dan mengubahnya menjadi kenyataan melalui sarana teknologi. Realitas sebagai dasar tidak berarti membatasi kemungkinan, tetapi memastikan bahwa perwujudan kemungkinan didasarkan pada dasar yang andal.</p><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Realitas sebagai dasar adalah posisi fundamental Peradaban Simbiosis Jangkar, dan merupakan titik awal serta tujuan akhir dari semua teori dan praktik peradaban. Ia menuntut agar kita memiliki imajinasi yang terbuka, menyerap inspirasi dari fiksi dan legenda; dan pada saat yang sama memiliki semangat pragmatis yang ketat, menempatkan semua inspirasi di bawah verifikasi hukum nyata. Kekurangan fiksi dilengkapi dengan realitas, apa yang tidak ada dalam realitas diciptakan berdasarkan pembaruan hukum — prinsip ini secara organik menyatukan imajinasi dan realitas, inspirasi dan hukum, penciptaan dan verifikasi, memberikan jaminan metodologis yang andal untuk evolusi berkelanjutan peradaban simbiosis.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Gambaran Umum Kosmos Heng Yuan Zhou)</li><li>16-倍增果实技术化原理 (Prinsip Teknologisasi Buah Penggandaan)</li><li>84-考古协议总纲 (Kerangka Umum Protokol Arkeologi)</li></ul>',43)])])}const o=i(s,[["render",r]]);export{p as __pageData,o as default};
